using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DenticleSuitOmenData", menuName = "Data/Battle/Omens System/Omen Data/Cellarius/DenticleSuit Omen Data")]
public class DenticleSuitOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<CellariusOmensHandler>.Instance.OnPlayerCorruptedDenticleSuitAction = delegate(int corruptAmount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
		{
			if (!ReferenceSingleton<BattleHandler>.Instance.IsSourceEnemy(source) && corruptionPurifyModifierEnum != CorruptionPurifyModifierEnum.ANOMALY)
			{
				corruptAmount--;
				omenInstance.EnqueueOmenFeedbackAndPlay();
			}
			return corruptAmount;
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<CellariusOmensHandler>.Instance.OnPlayerCorruptedDenticleSuitAction = null;
	}
}
